create table if not exists public.idea_post_reactions (post_id uuid not null references public.idea_posts(id) on delete cascade,user_id uuid not null references auth.users(id) on delete cascade,reaction text not null check(reaction in ('like','dislike')),created_at timestamptz not null default now(),primary key(post_id,user_id));
create table if not exists public.idea_post_comments (id uuid primary key default gen_random_uuid(),post_id uuid not null references public.idea_posts(id) on delete cascade,user_id uuid not null references auth.users(id) on delete cascade,content text not null check(char_length(content) between 1 and 2000),created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table if not exists public.idea_post_reshares (post_id uuid not null references public.idea_posts(id) on delete cascade,user_id uuid not null references auth.users(id) on delete cascade,created_at timestamptz not null default now(),primary key(post_id,user_id));
alter table public.idea_post_reactions enable row level security; alter table public.idea_post_comments enable row level security; alter table public.idea_post_reshares enable row level security;
do $$ begin
 create policy "read post reactions" on public.idea_post_reactions for select to anon,authenticated using(true); create policy "users manage own reactions" on public.idea_post_reactions for insert to authenticated with check((select auth.uid())=user_id); create policy "users delete own reactions" on public.idea_post_reactions for delete to authenticated using((select auth.uid())=user_id);
 create policy "read post comments" on public.idea_post_comments for select to anon,authenticated using(true); create policy "users add comments" on public.idea_post_comments for insert to authenticated with check((select auth.uid())=user_id); create policy "users update own comments" on public.idea_post_comments for update to authenticated using((select auth.uid())=user_id) with check((select auth.uid())=user_id); create policy "users delete own comments" on public.idea_post_comments for delete to authenticated using((select auth.uid())=user_id);
 create policy "read post reshares" on public.idea_post_reshares for select to anon,authenticated using(true); create policy "users reshare" on public.idea_post_reshares for insert to authenticated with check((select auth.uid())=user_id); create policy "users remove reshare" on public.idea_post_reshares for delete to authenticated using((select auth.uid())=user_id);
 exception when duplicate_object then null; end $$;